    "emptyContacts": "\u0412 \u044D\u0442\u043E\u043C \u0433\u043E\u0434\u0443 \u043D\u0435\u0442 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0445 \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u043E\u0432.",
    "wrappedShare": "\u041F\u043E\u0434\u0435\u043B\u0438\u0442\u044C\u0441\u044F \u0438\u0442\u043E\u0433\u0430\u043C\u0438 \u0433\u043E\u0434\u0430",
    "wrappedCardNote": "\u0418\u0437\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u0438\u0435 1080 \xD7 1920. \u0411\u0435\u0437 \u0438\u043C\u0435\u043D\u0438, \u0434\u0430\u043D\u043D\u044B\u0445 \u0440\u043E\u0436\u0434\u0435\u043D\u0438\u044F, \u043D\u0430\u0442\u0430\u043B\u044C\u043D\u044B\u0445 \u0433\u0440\u0430\u0434\u0443\u0441\u043E\u0432 \u0438 \u0434\u0430\u0442 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0445 \u043A\u043E\u043D\u0442\u0430\u043A\u0442\u043E\u0432.",
